effect.shader:
void main(){
    float ar=radians(arc);
    float ang=(acScreenNorm.x-0.5)*ar;
    float x=sin(ang)/sin(ar*0.5)*0.5+0.5;
    if(x<0.0||x>1.0){gl_FragColor=vec4(0.0);return;}
    vec4 col=texture2DCv(inputImg.texture, vec2(x, acScreenNorm.y));
    col.rgb *= mix(1.0, cos(ang), shade);
    gl_FragColor=col;
}
